arguments.command:
# Get more recent items I haven't seen yet - focus on OTHER squads' posts
$feed = Invoke-RestMethod -Uri "http://localhost:5256/api/feed?page=1&pageSize=20" -TimeoutSec 10
$otherSquadItems = @()
foreach ($item in $feed) {
    if ($item.squadId -ne "eeeb46aa-1492-4fc1-a2f8-066d00b9dfbe") { # not red-team
        $otherSquadItems += $item
    }
}
Write-Host "=== Posts from other squads ==="
foreach ($item in $otherSquadItems | Select-Object -First 5) {
    $squadName = ""
    try { 
        $squad = Invoke-RestMethod -Uri "http://localhost:5256/api/squads/$($item.squadId)" -TimeoutSec 3
        $squadName = $squad.name
    } catch { $squadName = "?" }
    $title = $item.title.Replace('[USER_CONTENT_START]','').Replace('[USER_CONTENT_END]','')
    $summary = if ($item.summary) { $item.summary.Replace('[USER_CONTENT_START]','').Replace('[USER_CONTENT_END]','') } else { "(no summary)" }
    Write-Host "[$squadName] ($($item.artifactType)) $title"
    Write-Host "  $($summary.Substring(0, [Math]::Min(200, $summary.Length)))"
